set-variable.value:
@{
      var raw = context.Request.Body.As<string>(preserveContent: true);
      if (string.IsNullOrWhiteSpace(raw)) { return "invalid_json"; }
      if (System.Text.Encoding.UTF8.GetByteCount(raw) > 1048576) { return "request_too_large"; }
      JObject body;
      try { body = JObject.Parse(raw); }
      catch (Newtonsoft.Json.JsonReaderException) { return "invalid_json"; }
      if (body["model"]?.Type != JTokenType.String || (string)body["model"] != "service-default") { return "invalid_model"; }
      var responses = context.Operation.Id == "sdk-responses";
      if (responses) {
        if (body["input"] == null || (body["input"].Type != JTokenType.Array && body["input"].Type != JTokenType.String)) { return "invalid_input"; }
      } else {
        if (body["messages"]?.Type != JTokenType.Array || !body["messages"].HasValues) { return "invalid_messages"; }
      }
      var allowed = responses
        ? new string[] { "model", "input", "instructions", "tools", "tool_choice", "stream", "store", "temperature", "top_p", "max_output_tokens", "parallel_tool_calls", "text", "reasoning", "include", "metadata", "background", "truncation" }
        : new string[] { "model", "messages", "tools", "tool_choice", "stream", "store", "temperature", "top_p", "max_tokens", "max_completion_tokens", "stream_options", "parallel_tool_calls", "response_format", "n" };
      if (body.Properties().Any(p => !allowed.Contains(p.Name))) { return "unsupported_field"; }
      if (body["stream"] != null && body["stream"].Type != JTokenType.Boolean) { return "invalid_stream"; }
      if (body["store"] != null && (body["store"].Type != JTokenType.Boolean || (bool)body["store"])) { return "provider_state_not_allowed"; }
      if (body["background"] != null && (body["background"].Type != JTokenType.Boolean || (bool)body["background"])) { return "background_not_allowed"; }
      if (body["truncation"] != null && (body["truncation"].Type != JTokenType.String || (string)body["truncation"] != "disabled")) { return "truncation_not_allowed"; }
      if (body["n"] != null && (body["n"].Type != JTokenType.Integer || body["n"].ToString() != "1")) { return "multiple_choices_not_allowed"; }
      foreach (var field in new string[] { "max_tokens", "max_completion_tokens", "max_output_tokens" }) {
        if (body[field] != null) {
          int limit;
          if (body[field].Type != JTokenType.Integer || !int.TryParse(body[field].ToString(), out limit) || limit < 1 || limit > 256) { return "output_limit_exceeded"; }
        }
      }
      if (body["max_tokens"] != null && body["max_completion_tokens"] != null) { return "conflicting_output_limits"; }
      return "";
    }

return-response.set-body:
@{
            var code = (string)context.Variables["validationError"];
            return new JObject(new JProperty("error", new JObject(new JProperty("code", code), new JProperty("type", "invalid_request_error"), new JProperty("message", code)))).ToString();
          }

inbound.set-body:
@{
      var body = context.Request.Body.As<JObject>(preserveContent: true);
      body["model"] = "__ROUTER_DEPLOYMENT__";
      body["store"] = false;
      if (context.Operation.Id == "sdk-responses") {
        body["background"] = false;
        body["truncation"] = "disabled";
        if (body["max_output_tokens"] == null) { body["max_output_tokens"] = 256; }
      } else {
        if (body["max_tokens"] == null && body["max_completion_tokens"] == null) { body["max_tokens"] = 256; }
      }
      return body.ToString();
    }
